('g3_2_sci_u1_L05_challenge#7','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C8',3,'mc','auto','고체와 액체에 모두 해당하는 것은 무엇인가요?',ARRAY['SC3-2-u1-X20','SC3-2-u1-X16']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C8","difficulty":3,"kind":"mc","stem":"고체와 액체에 모두 해당하는 것은 무엇인가요?","options":[{"t":"눈으로 볼 수 있다","correct":true},{"t":"손으로 잡을 수 있다","mis":"SC3-2-u1-X20"},{"t":"담는 용기에 관계없이 모양이 그대로다","mis":"SC3-2-u1-X16"},{"t":"흐르는 성질이 있다","mis":"SC3-2-u1-X16"}],"explanation":["나무 블록과 물을 견줘요.","둘 다 보여요.","눈으로 볼 수 있어요."]}'::jsonb),
