('g3_2_sci_u1_L08_basic#6','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'mc','auto','쓰임새 있는 물체를 설계하는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X31']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"mc","stem":"쓰임새 있는 물체를 설계하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"필요한 물체 찾기 → 알맞은 물질의 성질 고르기 → 설계도 그리고 소개하기","correct":true},{"t":"설계도 그리기 → 필요한 물체 찾기 → 물질 고르기","mis":"SC3-2-u1-X31"},{"t":"가장 비싼 물질 고르기 → 설계도 그리기 → 소개하기","mis":"SC3-2-u1-X31"},{"t":"소개하기 → 설계도 그리기 → 필요한 물체 찾기","mis":"SC3-2-u1-X31"}],"explanation":["먼저 무엇이 필요한지 찾아요.","그다음 물질을 골라요.","마지막에 그리고 소개해요."]}'::jsonb),
('g3_2_sci_u1_L08_basic#7','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'blank','auto','설계한 물체의 좋은 점은 물질의 (    )과 이어서 말해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X31']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"blank","stem":"설계한 물체의 좋은 점은 물질의 (    )과 이어서 말해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"성질","correct":true},{"t":"가격","mis":"SC3-2-u1-X31"},{"t":"이름","mis":"SC3-2-u1-X31"},{"t":"개수","mis":"SC3-2-u1-X31"}],"explanation":["철이 단단해서 좋아요.","단단함은 무엇일까요?","성질이에요."]}'::jsonb),
('g3_2_sci_u1_L08_basic#8','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'ox','auto','친구 설계의 보완할 점은 더 좋은 방법과 함께 말해요.',ARRAY['SC3-2-u1-X33']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"ox","stem":"친구 설계의 보완할 점은 더 좋은 방법과 함께 말해요.","answer":"O","reason_options":[{"t":"보완할 점은 설계를 더 좋게 만드는 도움말이기 때문에","correct":true},{"t":"보완할 점은 잘못을 찾아 흉보는 것이기 때문에","mis":"SC3-2-u1-X33"}],"mis":"SC3-2-u1-X33","explanation":["보완할 점의 뜻을 떠올려요.","더 좋게 만들어요.","그래서 O예요."]}'::jsonb),
('g3_2_sci_u1_L08_basic#9','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'mc','auto','독서대 앞판을 유리로 만들면 좋은 점은 무엇인가요?',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"mc","stem":"독서대 앞판을 유리로 만들면 좋은 점은 무엇인가요?","options":[{"t":"투명해서 책 글씨가 잘 보인다","correct":true},{"t":"단단해서 무거운 책을 버틴다","mis":"SC3-2-u1-X32"},{"t":"잘 미끄러지지 않는다","mis":"SC3-2-u1-X32"},{"t":"가벼워서 들고 다니기 좋다","mis":"SC3-2-u1-X32"}],"explanation":["유리의 성질이에요.","속이 비쳐요.","글씨가 잘 보여요."]}'::jsonb),
('g3_2_sci_u1_L08_basic#10','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',3,'mc','auto','친구 설계의 보완할 점을 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X33']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"친구 설계의 보완할 점을 알맞게 말한 것은 무엇인가요?","options":[{"t":"「유리는 깨질 수 있으니 테두리를 고무로 감싸면 어떨까?」","correct":true},{"t":"「그림이 이상해. 다시 그려.」","mis":"SC3-2-u1-X33"},{"t":"「이 설계는 별로야.」","mis":"SC3-2-u1-X33"},{"t":"「내 설계가 더 좋아.」","mis":"SC3-2-u1-X33"}],"explanation":["더 좋은 방법이 있나요?","대안을 찾아요.","고무로 감싸자는 말이에요."]}'::jsonb),
('g3_2_sci_u1_L08_challenge#1','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',2,'sa','auto','책을 세워 두어 고개를 숙이지 않고 읽게 해 주는 물체를 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"sa","stem":"책을 세워 두어 고개를 숙이지 않고 읽게 해 주는 물체를 세 글자로 쓰세요.","answer":["독서대"],"explanation":["책을 세워요.","독◯◯예요.","독서대예요."],"mis":"SC3-2-u1-X32"}'::jsonb),
('g3_2_sci_u1_L08_challenge#2','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',2,'mc','auto','물질의 성질로 좋은 점을 설명한 것은 무엇인가요?',ARRAY['SC3-2-u1-X31']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"mc","stem":"물질의 성질로 좋은 점을 설명한 것은 무엇인가요?","options":[{"t":"「철이 단단해서 무거운 책도 버텨요.」","correct":true},{"t":"「그냥 마음에 들어서 좋아요.」","mis":"SC3-2-u1-X31"},{"t":"「들고 다니면 멋있어 보여요.」","mis":"SC3-2-u1-X31"},{"t":"「비싼 물질이라서 좋아요.」","mis":"SC3-2-u1-X31"}],"explanation":["성질이 들어 있나요?","단단함이 성질이에요.","철이 단단하다는 말이에요."]}'::jsonb),
('g3_2_sci_u1_L08_challenge#3','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'error','auto','독서대 설계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"error","stem":"독서대 설계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「밀리지 않게 독서대 바닥에 유리를 붙일래.」","correct":true,"mis_target":"SC3-2-u1-X32"},{"t":"친구 나 — 「손잡이는 플라스틱으로 하면 좋아하는 색으로 만들 수 있어.」","mis":"SC3-2-u1-X32"},{"t":"친구 다 — 「받침대는 단단한 철로 하자.」","mis":"SC3-2-u1-X32"}],"explanation":["미끄럼을 막는 물질은요?","고무예요.","친구 가가 잘못 말했어요."]}'::jsonb),
('g3_2_sci_u1_L08_challenge#4','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'mc','auto','친구 나의 보관함 설계에서 쓰임새에 맞지 않는 부분과 바르게 고친 것은 무엇인가요?',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"친구 나의 보관함 설계에서 쓰임새에 맞지 않는 부분과 바르게 고친 것은 무엇인가요?","options":[{"t":"㉣ 몸통 — 유리 대신 가벼운 플라스틱으로 바꾼다","correct":true},{"t":"㉠ 뚜껑 — 유리 대신 철로 바꾼다","mis":"SC3-2-u1-X32"},{"t":"㉡ 바닥 — 고무 대신 유리로 바꾼다","mis":"SC3-2-u1-X32"},{"t":"㉢ 손잡이 — 철 대신 유리로 바꾼다","mis":"SC3-2-u1-X32"}],"explanation":["쓰임새를 하나씩 따져요.","들고 다니려면 가벼워야 해요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 속이 들여다보이는 뚜껑 — 유리","㉡ 책상에서 밀리지 않는 바닥 — 고무","㉢ 튼튼한 손잡이 — 철","㉣ 가볍게 들고 다니는 몸통 — 유리"],"title":"친구 나의 보관함 설계"}}'::jsonb),
('g3_2_sci_u1_L08_challenge#5','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'mc','auto','친구 설계를 볼 때 살필 것으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X31','SC3-2-u1-X33']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"친구 설계를 볼 때 살필 것으로 알맞은 것은 무엇인가요?","options":[{"t":"여러 물질의 성질을 이용했나요?","correct":true},{"t":"가장 비싼 물질을 썼나요?","mis":"SC3-2-u1-X31"},{"t":"친구보다 빨리 끝냈나요?","mis":"SC3-2-u1-X33"},{"t":"색칠을 가장 많이 했나요?","mis":"SC3-2-u1-X31"}],"explanation":["생각이 잘 드러났는지 봐요.","생활에서 쓸 수 있는지 봐요.","성질을 이용했는지 봐요."]}'::jsonb),
('g3_2_sci_u1_L08_challenge#6','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'match','auto','물질의 성질과 독서대의 좋은 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"match","stem":"물질의 성질과 독서대의 좋은 점을 알맞게 이으세요.","pairs":[{"l":"철이 단단해요","r":"무거운 책도 버텨요"},{"l":"플라스틱이 가벼운 편이에요","r":"들고 다니기 좋아요"},{"l":"고무가 잘 미끄러지지 않아요","r":"책상 위에서 밀리지 않아요"}],"mis":"SC3-2-u1-X31","explanation":["성질과 좋은 점을 이어요.","단단하면 버텨요.","가벼우면 들고 다녀요."]}'::jsonb),
('g3_2_sci_u1_L08_challenge#7','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'mc','auto','잘한 점과 보완할 점을 모두 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X33']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"잘한 점과 보완할 점을 모두 알맞게 말한 것은 무엇인가요?","options":[{"t":"「받침대가 튼튼해서 좋아. 높이를 바꿀 수 있으면 더 좋겠어.」","correct":true},{"t":"「받침대가 튼튼해서 좋아.」","mis":"SC3-2-u1-X33"},{"t":"「높이가 이상해. 다시 만들어.」","mis":"SC3-2-u1-X33"},{"t":"「다 별로야.」","mis":"SC3-2-u1-X33"}],"explanation":["잘한 점이 있나요?","대안도 있나요?","둘 다 있는 말이에요."]}'::jsonb),
('g3_2_sci_u1_L08_challenge#8','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',4,'mc','auto','어린이들이 들고 다니며 쓰는 물통을 설계해요. 가볍고, 떨어뜨려도 잘 깨지지 않고, 책상에서 잘 미끄러지지 않게 하려면 어떻게 설계하면 좋을까요?',ARRAY['SC3-2-u1-X32','SC3-2-u1-X31']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C13","difficulty":4,"kind":"mc","stem":"어린이들이 들고 다니며 쓰는 물통을 설계해요. 가볍고, 떨어뜨려도 잘 깨지지 않고, 책상에서 잘 미끄러지지 않게 하려면 어떻게 설계하면 좋을까요?","options":[{"t":"몸통은 플라스틱으로 하고 바닥에 고무를 붙인다","correct":true},{"t":"몸통을 유리로 하고 바닥에 유리를 붙인다","mis":"SC3-2-u1-X32"},{"t":"모든 부분을 무거운 철로만 만든다","mis":"SC3-2-u1-X32"},{"t":"가장 비싼 물질을 골라 만든다","mis":"SC3-2-u1-X31"}],"explanation":["필요한 성질을 찾아요.","가볍고 미끄러지지 않아야 해요.","플라스틱과 고무예요."]}'::jsonb),
('g3_2_sci_u1_L08_challenge#9','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',4,'mc','auto','단원 낱말을 「물질의 종류」와 「물질의 상태」로 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X05']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C13","difficulty":4,"kind":"mc","stem":"단원 낱말을 「물질의 종류」와 「물질의 상태」로 바르게 나눈 것은 무엇인가요?","options":[{"t":"종류: 플라스틱, 나무 / 상태: 고체, 기체","correct":true},{"t":"종류: 고체, 나무 / 상태: 플라스틱, 기체","mis":"SC3-2-u1-X30"},{"t":"종류: 고체, 기체 / 상태: 플라스틱, 나무","mis":"SC3-2-u1-X30"},{"t":"종류: 물체, 물질 / 상태: 플라스틱, 고체","mis":"SC3-2-u1-X05"}],"explanation":["무엇으로 되어 있나요?","어떤 상태인가요?","플라스틱·나무는 종류예요."]}'::jsonb),
('g3_2_sci_u1_L08_challenge#10','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',4,'essay','teacher','생활에서 필요한 물체 하나를 설계하세요. 물체의 이름과 쓰임새를 쓰고, 부분 두 곳 이상에 어떤 물질을 쓸지와 그 물질의 성질 때문에 생기는 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C13","difficulty":4,"kind":"essay","stem":"생활에서 필요한 물체 하나를 설계하세요. 물체의 이름과 쓰임새를 쓰고, 부분 두 곳 이상에 어떤 물질을 쓸지와 그 물질의 성질 때문에 생기는 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 비 오는 날 교실 앞에 두는 우산꽂이를 설계한다. 통은 단단한 철로 만들어 우산을 많이 꽂아도 넘어지거나 찌그러지지 않게 한다. 바닥에는 잘 미끄러지지 않는 고무를 붙여 밀리지 않게 한다. 이름표는 색깔을 다양하게 만들 수 있는 플라스틱으로 만들어 반마다 다른 색으로 꾸민다.","scoring_points":["물체의 이름과 쓰임새를 썼는가","부분 두 곳 이상에 물질을 정했는가","좋은 점을 물질의 성질과 이어 썼는가"]},"explanation":["물체를 정해요.","부분마다 물질을 골라요.","성질과 좋은 점을 이어요."]}'::jsonb),
