('g3_2_sci_u1_review_d#22','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C14',3,'ox','auto','3D 프린팅 전문가는 제품을 디자인하고 인쇄한 뒤 다듬어요.',ARRAY['SC3-2-u1-X36']::text[],false,'{"seq":22,"concept":"SC3-2-u1-C14","difficulty":3,"kind":"ox","stem":"3D 프린팅 전문가는 제품을 디자인하고 인쇄한 뒤 다듬어요.","answer":"O","reason_options":[{"t":"3D 프린터로 제품을 만드는 일을 하기 때문에","correct":true},{"t":"환자를 진찰하는 일을 하기 때문에","mis":"SC3-2-u1-X36"}],"mis":"SC3-2-u1-X36","explanation":["3D 프린터와 관련된 일이에요.","디자인하고 인쇄해요.","그래서 O예요."]}'::jsonb),
('g3_2_sci_u1_review_d#23','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C3',4,'mc','auto','「공원의 분수대 물, 풍선 속 공기, 나무 의자」를 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X21','SC3-2-u1-X30','SC3-2-u1-X05']::text[],false,'{"seq":23,"concept":"SC3-2-u1-C3","difficulty":4,"kind":"mc","stem":"「공원의 분수대 물, 풍선 속 공기, 나무 의자」를 알맞게 말한 것은 무엇인가요?","options":[{"t":"셋 다 공간을 차지하는 물질이며, 차례로 액체, 기체, 고체이다","correct":true},{"t":"나무 의자만 물질이고 나머지는 물질이 아니다","mis":"SC3-2-u1-X21"},{"t":"셋 다 액체이다","mis":"SC3-2-u1-X30"},{"t":"셋 다 물체이고 물질은 하나도 없다","mis":"SC3-2-u1-X05"}],"explanation":["모두 공간을 차지해요.","상태를 하나씩 따져요.","액체, 기체, 고체예요."]}'::jsonb),
('g3_2_sci_u1_review_d#24','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C7',4,'essay','teacher','햇살반 일지 ④의 분리배출 기록에서 잘못된 곳을 찾아 바르게 고치고, 그렇게 고친 까닭을 물질의 성질로 쓰세요. 분리배출을 물질의 종류대로 해야 하는 까닭도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u1-C7","difficulty":4,"kind":"essay","stem":"햇살반 일지 ④의 분리배출 기록에서 잘못된 곳을 찾아 바르게 고치고, 그렇게 고친 까닭을 물질의 성질로 쓰세요. 분리배출을 물질의 종류대로 해야 하는 까닭도 쓰세요.","answer_guide":{"answer":"예: 요구르트병은 유리병류가 아니라 플라스틱류에 넣어야 한다. 요구르트병은 가볍고 색깔과 모양이 다양한 플라스틱이기 때문이다. 분리배출은 같은 물질끼리 모아야 다시 쓰기 쉬우므로 물질의 종류대로 해야 한다.","scoring_points":["잘못된 곳을 찾아 고쳤는가","고친 까닭을 물질의 성질로 썼는가","분리배출을 물질의 종류대로 해야 하는 까닭을 썼는가"]},"explanation":["잘못 넣은 것을 찾아요.","성질로 까닭을 써요.","분리배출의 까닭을 써요."],"asset":{"type":"passage","lines":["유리병류 — 빈 잼 유리병, 요구르트병","캔류 — 빈 철 캔","플라스틱류 — 페트병, 플라스틱 컵"],"title":"햇살반 일지 ④ 분리배출 당번 기록"}}'::jsonb),
('g3_2_sci_u1_review_d#25','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C6',4,'essay','teacher','「물체와 물질」 단원에서 배운 것을 바탕으로, 교실에서 쓰는 물체 하나를 골라 어떤 물질로 이루어졌는지 쓰고, 그 물질의 성질이 물체의 쓰임새에 어떻게 도움이 되는지 쓰세요. 물체 속에 고체가 아닌 상태가 있다면 그것도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u1-C6","difficulty":4,"kind":"essay","stem":"「물체와 물질」 단원에서 배운 것을 바탕으로, 교실에서 쓰는 물체 하나를 골라 어떤 물질로 이루어졌는지 쓰고, 그 물질의 성질이 물체의 쓰임새에 어떻게 도움이 되는지 쓰세요. 물체 속에 고체가 아닌 상태가 있다면 그것도 쓰세요.","answer_guide":{"answer":"예: 교실의 물병을 골랐다. 물병 몸통은 플라스틱으로 이루어져 있다. 플라스틱은 가벼운 편이라 들고 다니기 좋고 잘 깨지지 않아 떨어뜨려도 안전하다. 물병 속의 물은 액체라서 물병 모양을 따라 모양이 변하고, 물을 마시고 남은 공간에는 공기(기체)가 가득 차 있다.","scoring_points":["물체와 물질을 바르게 썼는가","물질의 성질을 쓰임새와 이어 썼는가","고체가 아닌 상태를 찾아 썼는가"]},"explanation":["물체를 골라요.","성질과 쓰임새를 이어요.","다른 상태도 찾아요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SC3-2-u2-C1','sci',3,2,'u2',1,'지구의 다양한 모습 — 지구의 육지와 바다에는 사막, 북극의 빙하, 고래가 사는 바다, 강, 호수, 들판, 갯벌처럼 다양한 모습이 있음 · 달 표면처럼 지구 밖의 모습은 오늘 떠올리는 지구의 모습이 아님 · 장소마다 볼 수 있는 모습이 다름(빙하-북극곰, 갯벌-게·짱뚱어, 사막-모래 언덕)',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],1),
('SC3-2-u2-C2','sci',3,2,'u2',1,'다른 그림 찾기 방법과 태도 — 두 그림 (가)·(나)를 장소마다 하나씩 견주어 다른 부분을 찾음 · 찾으면 찾은 장소를 말해 알려 줌 · 구역을 나누어 함께 찾고, 친구 생각이 달라도 존중함 · 이기고 지는 놀이가 아니라 지구의 모습을 함께 살펴보는 놀이',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],2),
('SC3-2-u2-C3','sci',3,2,'u2',2,'공기를 느낄 수 있는 상황 — 공기는 눈에 보이지 않지만 우리 주변 어디에나 있음 · 비눗방울 안을 공기가 채움 · 연, 바람개비, 돛단배는 바람을 받아 움직이고, 숨 쉬기·풍선 불기는 숨으로, 부채질은 바람을 일으켜 공기를 느낌 · 열기구·패러글라이딩을 하는 곳에도 공기가 있음',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],3),
('SC3-2-u2-C4','sci',3,2,'u2',2,'대기 — 지구를 둘러싸고 있는 공기를 대기라고 함 · 바람이 불 때, 숨을 쉴 때 대기를 느낄 수 있음 · 대기가 없으면 숨을 쉴 수 없음',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],4),
('SC3-2-u2-C5','sci',3,2,'u2',3,'육지와 바다 — 땅으로 이루어진 곳이 육지, 물로 덮여 있는 곳이 바다 · 육지에서는 산, 들, 강, 계곡, 사막, 빙하 등 다양한 모습을 볼 수 있음 · 우주에서 본 지구가 여러 색인 것은 다양한 모습이 있기 때문',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],5),
('SC3-2-u2-C6','sci',3,2,'u2',3,'붙임쪽지로 육지와 바다 넓이 견주기 — 지구본 칸마다 육지가 절반이 넘으면 육지 붙임쪽지, 바다가 절반이 넘으면 바다 붙임쪽지를 겹치지 않게 붙임 · 붙임쪽지가 더 많이 필요할수록 더 넓은 곳 · 개수는 모둠마다 달라도 바다가 육지보다 넓다는 결과는 같음',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],6),
('SC3-2-u2-C7','sci',3,2,'u2',3,'육지의 물과 바닷물 — 지구의 물은 육지의 물과 바닷물로 나눔 · 육지의 물은 강, 호수, 계곡, 빙하 등에서 찾고 바다에는 바닷물이 있음 · 지구의 물은 대부분 바닷물이라 우리가 쓸 수 있는 육지의 물은 적어 아껴 써야 함',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],7),
('SC3-2-u2-C8','sci',3,2,'u2',4,'육지의 물과 바닷물을 가열하는 실험 방법과 안전 — 두 물을 같은 양씩 증발 접시에 담고 끓임쪽(물이 갑자기 끓어오르지 않게 넣는 돌이나 유리 조각)을 넣어 물이 없어질 때까지 가열함 · 실험 재료는 맛보지 않음 · 보안경과 면장갑을 쓰고, 증발 접시는 집게로 옮기며, 핫플레이트는 전원을 끈 뒤에도 뜨거움',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],8),
('SC3-2-u2-C9','sci',3,2,'u2',4,'바닷물의 특징 — 육지의 물은 가열해도 남는 물질이 없지만 바닷물은 하얗고 거칠거칠하며 냄새가 없는 물질이 남음 · 남는 물질의 대부분은 소금 · 바닷물은 소금이 녹아 있어 짠맛이 나고 사람이 마시거나 농사를 짓는 데 알맞지 않음',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],9),
('SC3-2-u2-C10','sci',3,2,'u2',5,'지형과 바닷가 지형의 특징 — 땅의 생김새를 지형이라고 함 · 바닷가에서는 가파른 절벽, 바위에 구멍이 뚫려 물이 지나가는 동굴, 고운 흙이나 모래가 넓게 펼쳐진 모래사장, 진흙이 보이고 색이 어두운 갯벌 등을 볼 수 있음',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],10),
('SC3-2-u2-C11','sci',3,2,'u2',5,'바닷가 지형 조사·분류·공유 — 스마트 기기나 여행 사진으로 바닷가 지형을 조사함 · 바위로 이루어진 지형(절벽·동굴)과 모래나 흙으로 이루어진 지형(모래사장·갯벌)으로 나눌 수 있음 · 네 가지 외에도 바닷가 지형이 더 있음 · 사진을 나눌 때 비방하는 댓글을 달지 않고 친구 생각을 존중함',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],11),
('SC3-2-u2-C12','sci',3,2,'u2',6,'밀물과 썰물 — 바닷물이 바다에서 육지 쪽으로 밀려 들어오는 것이 밀물, 육지에서 바다 쪽으로 빠져나가는 것이 썰물 · 밀물 때 바닷물의 높이가 높아지고 썰물 때 낮아짐 · 바닷물의 높이는 시간에 따라 달라짐',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],12),
('SC3-2-u2-C13','sci',3,2,'u2',6,'밀물·썰물 모형과 바닷가 모습 — 모형에서 밀물 때는 모래사장의 표지판이 잠기고 바닷길이 사라지며, 썰물 때는 표지판과 바닷길이 드러남 · 바닷길이 드러난 썰물 때 걸어서 섬에 갈 수 있음 · 파도가 잠깐 밀려왔다 쓸려 나가는 것과 달리 밀물과 썰물은 일정 시간 동안 이어짐',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],13),
('SC3-2-u2-C14','sci',3,2,'u2',7,'갯벌의 뜻과 우리나라 갯벌 — 갯벌은 밀물 때 바닷물에 잠기고 썰물 때 바닷물 밖으로 드러나는 땅 · 우리나라 갯벌은 밀물과 썰물 때 바닷물의 높이 차가 큰 서해안과 남해안에 주로 있고, 높이 차가 작은 동해안에서는 찾아보기 어려움 · 칠게, 갯지렁이, 바지락, 낙지, 알락꼬리마도요, 퉁퉁마디가 삶',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],14),
('SC3-2-u2-C15','sci',3,2,'u2',7,'갯벌의 역할(가치) — 조개, 게 등 다양한 생물의 터전 · 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 하고 갯벌 생물이 오염 물질을 분해함 · 철새와 물고기가 알을 낳고 새끼를 기르기 좋은 환경 · 홍수나 태풍의 피해를 줄여 줌 · 게와 지렁이가 굴을 파 신선한 공기가 드나들어 갯벌이 썩지 않음',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],15),
('SC3-2-u2-C16','sci',3,2,'u2',7,'갯벌 보전 — 갯벌은 우리에게 많은 도움을 주는 소중한 땅이라 잘 보전해야 함 · 쓰레기를 함부로 버리지 않고 체험 때 생물을 함부로 잡지 않음 · 갯벌은 바닷물이 드나드는 곳이라 오염된 갯벌을 울타리로 막아도 바다 전체를 오염시킬 수 있음 · 갯벌의 가치를 알림',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],16),
('SC3-2-u2-C17','sci',3,2,'u2',8,'갯벌 보전 홍보 자료 만들기 — 기름 유출 사고 같은 문제 상황 → 계획서(해결 방법·역할 나누기·넣고 싶은 내용·보완할 점) → 만들기 → 소통하기 · 홍보 자료에는 갯벌의 가치와 보전의 필요성, 우리가 할 일을 담음 · 가져온 자료는 출처를 밝힘 · 다른 모둠 자료는 잘 듣고 잘한 점을 칭찬하며 보완할 점은 함께 고침 · 화려한 꾸밈보다 가치와 필요성이 잘 드러나는 것이 중요',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],17),
('SC3-2-u2-C18','sci',3,2,'u2',9,'바다에서 얻는 먹을거리와 해조류 — 바다는 살아가는 데 필요한 자원을 많이 줌 · 게, 조개 같은 식량과 김, 미역, 다시마 같은 해조류를 얻음 · 해조류는 화장품이나 건강식품의 재료로도 쓰임',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],18),
('SC3-2-u2-C19','sci',3,2,'u2',9,'바다에서 얻는 소금·마실 물·전기 — 바닷물을 끌어 들여 논처럼 만든 염전에서 바닷물을 햇빛에 두어 소금을 얻음(우리나라 염전은 서해안에 많음) · 바닷물을 이용 가능한 물로 바꾸는 기술은 물 부족 문제 해결에 도움 · 파도가 치는 힘이나 밀물과 썰물의 차이로 환경 오염 걱정이 없는 전기를 만듦 · 해양 공학자, 해양 연구원이 바다를 연구함',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],19)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SC3-2-u2-X01','sci',3,'u2',ARRAY['SC3-2-u2-C1']::text[],'달 표면처럼 지구 밖의 모습을 지구의 모습으로 여기거나, 지구에 한두 가지 모습만 있다고 여긴다','지구의 다양한 모습'),
('SC3-2-u2-X02','sci',3,'u2',ARRAY['SC3-2-u2-C1']::text[],'장소와 그곳에서 볼 수 있는 모습을 잘못 잇는다(빙하에 게와 짱뚱어, 사막에 북극곰 등)','빙하 · 갯벌 · 사막'),
('SC3-2-u2-X03','sci',3,'u2',ARRAY['SC3-2-u2-C2']::text[],'두 그림을 견준 결과를 뒤바꾸거나 한 그림만 보고 다른 부분을 말한다','장소마다 하나씩 견주어요'),
('SC3-2-u2-X04','sci',3,'u2',ARRAY['SC3-2-u2-C2']::text[],'다른 그림 찾기 방법과 태도를 잘못 안다(먼저 크게 외치기, 혼자만 알기, 정답만 가리키기, 이기고 지는 놀이로 여기기 등)','찾은 장소를 말해요'),
('SC3-2-u2-X05','sci',3,'u2',ARRAY['SC3-2-u2-C3','SC3-2-u2-C4']::text[],'공기는 눈에 보이지 않으니 없다고 여기거나 비눗방울 속이 비어 있다고 여긴다','보이지 않아도 있어요'),
('SC3-2-u2-X06','sci',3,'u2',ARRAY['SC3-2-u2-C3']::text[],'공기는 하늘이나 바람 부는 곳처럼 정해진 곳에만 있다고 여긴다','어디에나 있어요'),
('SC3-2-u2-X07','sci',3,'u2',ARRAY['SC3-2-u2-C3']::text[],'공기를 느끼는 경험을 잘못 고르거나(컵에 담긴 물 등), 바람을 받아 움직이는 것과 숨으로 느끼는 것을 뒤바꾼다','바람 · 숨 · 부채'),
('SC3-2-u2-X08','sci',3,'u2',ARRAY['SC3-2-u2-C4']::text[],'대기의 뜻을 잘못 안다(바람, 구름, 바다, 우주 등으로)','지구를 둘러싼 공기'),
('SC3-2-u2-X09','sci',3,'u2',ARRAY['SC3-2-u2-C4']::text[],'대기가 없어도 우리 생활에 아무 변화가 없다고 여긴다','숨을 쉴 수 있게 해요'),
('SC3-2-u2-X10','sci',3,'u2',ARRAY['SC3-2-u2-C5']::text[],'육지와 바다의 뜻을 뒤바꾸거나 육지의 모습(강, 계곡, 빙하 등)을 바다로 여긴다','땅 · 물로 덮인 곳'),
('SC3-2-u2-X11','sci',3,'u2',ARRAY['SC3-2-u2-C5','SC3-2-u2-C6']::text[],'육지에 볼 수 있는 모습이 더 많으니 육지가 바다보다 넓다고 여긴다','바다가 더 넓어요'),
('SC3-2-u2-X12','sci',3,'u2',ARRAY['SC3-2-u2-C6']::text[],'붙임쪽지 활동 방법을 잘못 안다(절반 기준을 뒤바꾸기, 겹쳐 붙이기, 개수가 모든 모둠에서 같아야 한다고 여기기 등)','절반이 넘는 쪽으로'),
('SC3-2-u2-X13','sci',3,'u2',ARRAY['SC3-2-u2-C6']::text[],'붙임쪽지 결과를 거꾸로 읽는다(적게 붙인 곳이 넓다, 개수로는 알 수 없다 등)','많이 붙인 곳이 넓어요'),
('SC3-2-u2-X14','sci',3,'u2',ARRAY['SC3-2-u2-C7']::text[],'육지의 물과 바닷물이 있는 곳을 뒤바꾼다(강·호수를 바닷물로, 바다에서 육지의 물을 찾는 등)','강 · 호수 · 계곡 · 빙하'),
('SC3-2-u2-X15','sci',3,'u2',ARRAY['SC3-2-u2-C7','SC3-2-u2-C9']::text[],'지구의 물은 대부분 육지의 물이라고 여기거나 쓸 수 있는 물이 많아 아끼지 않아도 된다고 여긴다','대부분이 바닷물'),
('SC3-2-u2-X16','sci',3,'u2',ARRAY['SC3-2-u2-C8']::text[],'실험 재료를 맛보거나 안전 약속을 지키지 않는다(맨손으로 옮기기, 전원을 끈 바로 뒤 만지기, 보안경 안 쓰기 등)','맛보지 않기 · 집게 · 보안경'),
('SC3-2-u2-X17','sci',3,'u2',ARRAY['SC3-2-u2-C8']::text[],'끓임쪽의 쓰임이나 실험 방법을 잘못 안다(두 물을 같은 방법으로 가열하지 않기 등)','같은 양 · 같은 방법'),
('SC3-2-u2-X18','sci',3,'u2',ARRAY['SC3-2-u2-C9']::text[],'육지의 물도 가열하면 남는 물질이 있다고 여기거나, 바닷물에서 남는 물질이 없다고 여긴다','바닷물만 남아요'),
('SC3-2-u2-X19','sci',3,'u2',ARRAY['SC3-2-u2-C9']::text[],'남은 물질의 관찰 결과(색깔·촉감·냄새)를 잘못 안다','하얗고 거칠거칠'),
('SC3-2-u2-X20','sci',3,'u2',ARRAY['SC3-2-u2-C9']::text[],'바닷물이 짠 까닭을 잘못 안다(모래, 흙, 설탕 등)','소금이 녹아 있어요'),
('SC3-2-u2-X21','sci',3,'u2',ARRAY['SC3-2-u2-C9']::text[],'바닷물을 그대로 마시거나 농사에 써도 된다고 여긴다','마시기에 알맞지 않아요'),
('SC3-2-u2-X22','sci',3,'u2',ARRAY['SC3-2-u2-C10']::text[],'지형의 뜻을 잘못 안다(날씨, 바닷물, 대기 등으로)','땅의 생김새'),
('SC3-2-u2-X23','sci',3,'u2',ARRAY['SC3-2-u2-C10']::text[],'바닷가 지형의 특징을 뒤바꾼다(절벽에 구멍, 갯벌이 가파름, 모래사장 색이 어두움 등)','가파른 · 구멍 · 모래 · 진흙'),
('SC3-2-u2-X24','sci',3,'u2',ARRAY['SC3-2-u2-C10','SC3-2-u2-C11']::text[],'바닷가 지형은 정해진 몇 가지뿐이라고 여기거나 사막처럼 바닷가가 아닌 곳의 모습을 바닷가 지형으로 여긴다','네 가지 외에도 있어요'),
('SC3-2-u2-X25','sci',3,'u2',ARRAY['SC3-2-u2-C11']::text[],'바위로 이루어진 지형과 모래나 흙으로 이루어진 지형을 잘못 가른다','바위 · 모래나 흙'),
('SC3-2-u2-X26','sci',3,'u2',ARRAY['SC3-2-u2-C11']::text[],'지형을 조사하고 나눌 때 태도를 잘못 안다(비방하는 댓글, 관계없는 검색, 장난 등)','존중해요'),
('SC3-2-u2-X27','sci',3,'u2',ARRAY['SC3-2-u2-C12']::text[],'밀물과 썰물의 뜻을 뒤바꾼다','밀려 들어오면 밀물'),
('SC3-2-u2-X28','sci',3,'u2',ARRAY['SC3-2-u2-C12']::text[],'밀물·썰물 때 바닷물의 높이 변화를 뒤바꾼다','밀물 때 높아져요'),
('SC3-2-u2-X29','sci',3,'u2',ARRAY['SC3-2-u2-C13']::text[],'표지판·바닷길 같은 바닷가 모습을 밀물·썰물 때와 잘못 잇는다(걸어서 섬에 가는 때를 밀물로 등)','썰물 때 길이 드러나요'),
('SC3-2-u2-X30','sci',3,'u2',ARRAY['SC3-2-u2-C13']::text[],'파도가 밀려왔다 쓸려 나가는 것을 밀물·썰물과 같은 것으로 여긴다','파도는 잠깐'),
('SC3-2-u2-X31','sci',3,'u2',ARRAY['SC3-2-u2-C12','SC3-2-u2-C13']::text[],'바닷물의 높이는 언제나 같다고 여긴다','시간에 따라 달라져요'),
('SC3-2-u2-X32','sci',3,'u2',ARRAY['SC3-2-u2-C14']::text[],'갯벌의 뜻을 잘못 안다(언제나 잠긴 땅, 언제나 드러난 땅, 바위 지형 등)','잠기고 드러나는 땅'),
('SC3-2-u2-X33','sci',3,'u2',ARRAY['SC3-2-u2-C14']::text[],'우리나라 갯벌이 있는 곳과 그 까닭을 잘못 안다(동해안에 많다, 바닷물이 짜서 등)','서해안 · 남해안'),
('SC3-2-u2-X34','sci',3,'u2',ARRAY['SC3-2-u2-C14']::text[],'갯벌에 사는 생물을 잘못 알거나 갯벌에는 생물이 살지 않는다고 여긴다','칠게 · 바지락 · 낙지'),
('SC3-2-u2-X35','sci',3,'u2',ARRAY['SC3-2-u2-C15']::text[],'갯벌의 역할을 잘못 안다(쓸모없다, 땅을 오염시킨다, 바닷물을 짜게 한다 등)','생물의 터전 · 깨끗한 바다'),
('SC3-2-u2-X36','sci',3,'u2',ARRAY['SC3-2-u2-C15']::text[],'갯벌에서 일어나는 일과 그 좋은 점을 잘못 잇는다(굴 파기 → 썩지 않음 등)','하는 일과 좋은 점'),
('SC3-2-u2-X37','sci',3,'u2',ARRAY['SC3-2-u2-C16']::text[],'갯벌을 해치는 행동을 괜찮다고 여긴다(생물을 마음껏 잡기, 쓰레기 버리기 등)','함부로 잡지 않기'),
('SC3-2-u2-X38','sci',3,'u2',ARRAY['SC3-2-u2-C16']::text[],'오염된 갯벌은 울타리로 막아 두면 괜찮다고 여긴다','바닷물이 드나들어요'),
('SC3-2-u2-X39','sci',3,'u2',ARRAY['SC3-2-u2-C17']::text[],'홍보 자료의 내용과 만드는 과정을 잘못 안다(화려한 꾸밈이 가장 중요, 가치와 필요성 빠뜨리기, 계획·역할 없이 만들기, 출처 안 밝히기 등)','가치와 보전의 필요성'),
('SC3-2-u2-X40','sci',3,'u2',ARRAY['SC3-2-u2-C17']::text[],'다른 모둠 자료를 살필 때 비난하거나 자기 모둠 자랑만 하고, 보완할 점을 함께 고칠 방법 없이 말한다','잘한 점 먼저 · 함께 고쳐요'),
('SC3-2-u2-X41','sci',3,'u2',ARRAY['SC3-2-u2-C18']::text[],'바다에서 얻는 자원은 물고기 같은 먹을거리뿐이라고 여긴다','전기 · 소금 · 물'),
('SC3-2-u2-X42','sci',3,'u2',ARRAY['SC3-2-u2-C18']::text[],'해조류를 잘못 가르거나(조개·게를 해조류로) 해조류의 쓰임을 먹을거리로만 안다','김 · 미역 · 다시마'),
('SC3-2-u2-X43','sci',3,'u2',ARRAY['SC3-2-u2-C19']::text[],'바다 자원과 얻는 방법을 잘못 잇는다(소금을 파도로, 전기를 햇빛으로, 염전을 동해안으로 등)','소금은 햇빛, 전기는 바닷물의 움직임'),
('SC3-2-u2-X44','sci',3,'u2',ARRAY['SC3-2-u2-C19']::text[],'바다에서 얻는 전기와 바닷물을 바꾸는 기술의 좋은 점, 바다를 연구하는 사람을 잘못 안다','친환경 · 물 부족 · 해양 연구원')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
