('g3_2_sci_u2_L01_basic#4','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C1',1,'mc','auto','진흙이 펼쳐져 있고 게와 짱뚱어를 볼 수 있는 곳은 어디인가요?',ARRAY['SC3-2-u2-X02']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C1","difficulty":1,"kind":"mc","stem":"진흙이 펼쳐져 있고 게와 짱뚱어를 볼 수 있는 곳은 어디인가요?","options":[{"t":"갯벌","correct":true},{"t":"사막","mis":"SC3-2-u2-X02"},{"t":"빙하","mis":"SC3-2-u2-X02"},{"t":"들판","mis":"SC3-2-u2-X02"}],"explanation":["진흙을 떠올려요.","게가 살아요.","갯벌이에요."]}'::jsonb),
('g3_2_sci_u2_L01_basic#5','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C1',2,'match','auto','장소와 그곳에서 볼 수 있는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C1","difficulty":2,"kind":"match","stem":"장소와 그곳에서 볼 수 있는 모습을 알맞게 이으세요.","pairs":[{"l":"빙하","r":"북극곰"},{"l":"갯벌","r":"게와 짱뚱어"},{"l":"사막","r":"모래 언덕"}],"mis":"SC3-2-u2-X02","explanation":["장소를 하나씩 떠올려요.","얼음 위에는 북극곰이에요.","빙하-북극곰, 갯벌-게, 사막-모래 언덕이에요."]}'::jsonb),
('g3_2_sci_u2_L01_basic#6','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C2',2,'mc','auto','두 그림 견주기 기록에서 (나)에만 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X03']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C2","difficulty":2,"kind":"mc","stem":"두 그림 견주기 기록에서 (나)에만 있는 것은 무엇인가요?","options":[{"t":"호수","correct":true},{"t":"강 위의 돌","mis":"SC3-2-u2-X03"},{"t":"파도가 치는 모습","mis":"SC3-2-u2-X03"},{"t":"아무것도 없다","mis":"SC3-2-u2-X03"}],"explanation":["(가)와 (나)를 견줘요.","호수 줄을 읽어요.","(나)에만 호수가 있어요."],"asset":{"type":"passage","lines":["강 — (가) 강 위에 돌이 있어요. (나) 강 위에 돌이 없어요.","호수 — (가) 호수가 없어요. (나) 호수가 있어요.","모래사장 — (가) 파도가 쳐요. (나) 진흙이 펼쳐진 갯벌이 보여요.","모래사장 뒤 — (가) 산이 없어요. (나) 산이 있어요."],"title":"두 그림 견주기 기록"}}'::jsonb),
